// Main thread: fetch, WebSocket, and minimal SW registration
fetch('/api/feed')
  .then(r => r.json())
  .then(render)

const ws = new WebSocket('wss://example.com/feed');
ws.addEventListener('message', (ev) => {
  const update = JSON.parse(ev.data);
  // update data store and batch DOM updates
});

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js');
}

// Service Worker sketch (sw.js) for caching and offline support
self.addEventListener('install', e => {
  e.waitUntil(caches.open('v1').then(cache => cache.addAll(['/','/index.html','/app.js'])));
});
self.addEventListener('fetch', e => {
  e.respondWith(
    caches.match(e.request).then(r => r || fetch(e.request))
  );
});
```

